2	/**
3	 * decide_reask.ts  Ethe one second turn a run is allowed, and why it is being
4	 * asked for.
5	 *
6	 * An ending that calls two things, a run that stopped on a sentence having
7	 * changed nothing, and a run the loop guard stopped are different failures with
8	 * the same remedy: a user turn in the session, then the same atoma invocation
9	 * again. So a run gets at most ONE extra turn, and the ending is checked first  Ea
10	 * message that calls somebody has handed the work on and must not also be read
11	 * as stalled.
12	 *
13	 * This used to be inline in the agent step, and moved here with the rest of the
14	 * step's logic when the step outgrew GitHub's 21,000-character bound on one
15	 * expression. The behaviour is the one that shipped: the same checks, the same
16	 * injections, the same bounds.
17	 *
18	 * The scripts this orchestrates are spawned rather than imported, because that
19	 * is exactly how the runner called them  Esame argv, same fail-open shapes. A
20	 * check that cannot run is a machinery error here (it fails the step, leaving
21	 * the boundary flag unwritten), which is what the inline version's `-e` did.
22	 *
23	 * Prints `exit_code=<n>` and `ending_invalid=<bool>` to stdout  Ethe caller's
24	 * step reads both, because the ending classification below consumes the exit
25	 * code this may have rewritten (a person stopping during the second turn makes
26	 * the run a soft stop), and stdout is the only channel into the same step.
27	 */
28	import { spawnSync } from "node:child_process";
29	import { copyFileSync, existsSync, readFileSync, rmSync, writeFileSync } from "node:fs";
30	import { join } from "node:path";
31	import { parseArgs } from "node:util";
32	import { AGENT_DEFINITIONS_DIR } from "../../domain/machinery/machinery-layout.ts";
33	import { machineryRoot } from "../../adapters/runner/machinery.ts";
34	import { loopAbortFromSession } from "../../domain/work/loop-continuation.ts";
35	import { agentBudget, buildAgentEnv, changedSoFar } from "./lib/agent-env.ts";
36	import { launchAtoma } from "./lib/atoma-launch.ts";
37	import { defineScript } from "./lib/script-ref.ts";
38	import { parseSession } from "./read_run_ending.ts";
39	
40	export interface DecideReaskArgs {
41	  "run-dir": string;
42	  "tool-cache": string;
43	  "tools-file": string;
44	  "credentials-file": string;
45	  "stop-file": string;
46	  "deadline-at": string;
47	  "min-budget-secs": string;
48	  "exit-code": string;
49	}
50	
51	export const ref = defineScript<DecideReaskArgs>(import.meta.url);
52	
53	/** Runs one of the sibling scripts the way the runner always has, inheriting output. */
54	function sibling(script: string, args: string[]): void {
55	  const run = spawnSync("bun", ["run", join(import.meta.dir, script), ...args], { stdio: "inherit" });
56	  if (run.status !== 0) {
57	    throw new Error(`decide_reask: ${script} exited ${run.status}`);
58	  }
