62	  const { values } = parseArgs({
63	    args: Bun.argv.slice(2),
64	    options: {
65	      "run-dir": { type: "string" },
66	      "tool-cache": { type: "string" },
67	      "tools-file": { type: "string" },
68	      "credentials-file": { type: "string" },
69	      "stop-file": { type: "string" },
70	      "deadline-at": { type: "string" },
71	      "min-budget-secs": { type: "string" },
72	      "exit-code": { type: "string" },
73	    },
74	  });
75	  for (const required of ["run-dir", "tool-cache", "tools-file", "credentials-file", "stop-file", "deadline-at", "min-budget-secs", "exit-code"] as const) {
76	    if (values[required] === undefined) {
77	      console.error(`decide_reask: --${required} is required`);
78	      process.exit(2);
79	    }
80	  }
81	
82	  const runDir = values["run-dir"]!;
83	  const session = join(runDir, "session.json");
84	  const sessionBefore = join(runDir, "session_before_reask.json");
85	  const output = join(runDir, "atomaton_output.txt");
86	  const outputAgain = join(runDir, "atomaton_output_again.txt");
87	  const logs = join(runDir, "atomaton_logs.txt");
88	  const problemFile = join(runDir, "ending-problem.txt");
89	  const peopleFile = join(runDir, "callees.json");
90	  const stopFile = values["stop-file"]!;
91	  const root = machineryRoot() ?? ".";
92	
93	  const checkArgs = ["--output-file", output, "--def-dir", join(root, AGENT_DEFINITIONS_DIR), "--problem-file", problemFile, "--people-file", peopleFile];
94	  const envEntries = buildAgentEnv(process.env, {
95	    toolCache: values["tool-cache"]!,
96	    runDir,
97	  });
98	  const launchArgs = {
99	    agent: process.env.AGENT ?? "",
100	    machineryRoot: root,
101	    toolsFile: values["tools-file"]!,
102	    credentialsFile: values["credentials-file"]!,
103	    stopFile,
104	    session,
105	    logsFile: logs,
106	    appendLogs: true,
107	    envEntries,
108	  };
109	
110	  let exitCode = values["exit-code"]!;
111	  let endingInvalid = false;
112	
113	  // The reason for the second turn, if there is one. The ending check runs only
114	  // for a run that ended of its own accord: a run that was stopped or ran out of
115	  // time was cut off mid-sentence, and asking it to finish the sentence would be
116	  // asking it to ignore the person who said stop.
117	  //
118	  // A loop abort is the one ending that is not `completed` and is still asked. The
119	  // guard stopped a run that was working, the verdict in the session names exactly
120	  // what it repeated, and one turn is what turns that into a report a person can
121	  // read -- see `domain/work/loop-continuation.ts` for why that run is worth asking
122	  // and what it is told. The verdict is what is read, not the ending word or the exit
123	  // code: atoma records this abort as `failed`, so both of those say only that the run
124	  // did not finish.
125	  let reask = "";
126	  if (!existsSync(stopFile)) {
127	    if (exitCode === "0") {
128	      sibling("check_ending.ts", checkArgs);
129	      if (readFileSync(problemFile, "utf8").length > 0) {
130	        reask = "ending";
131	      } else {
132	        const stalled = spawnSync(
133	          "bun",
134	          ["run", join(import.meta.dir, "should_continue_stalled.ts"), "--session", session, "--output-file", output, "--def-dir", join(root, AGENT_DEFINITIONS_DIR), "--people-file", peopleFile, "--changed", String(changedSoFar(join(runDir, "atomaton_ops.log")))],
135	          { encoding: "utf8" },
136	        );
137	        if (stalled.status === 0 && stalled.stdout.trim() === "true") reask = "stalled";
138	      }
139	    } else if (loopAbortFromSession(parseSession(existsSync(session) ? readFileSync(session, "utf8") : undefined)) !== undefined) {
140	      reask = "loop";
141	    }
142	  }
143	
144	  if (reask !== "") {
145	    const { budget: reaskBudget, floored } = agentBudget(Number(values["deadline-at"]), Date.now() / 1000, Number(values["min-budget-secs"]));
146	    if (floored) {
147	      // No time for a second turn. An ending that calls two things is posted with
148	      // its calls left as text, and the result comment says so  Esee
149	      // post_result_comment.ts's --ending-invalid. A stalled run simply keeps the
150	      // message it ended on, and a loop abort keeps the ending and the verdict the
151	      // session already holds, which is what names the repeated call in its comment.
152	      if (reask === "ending") {
153	        console.error("::warning::the closing message calls more than one thing and there is no time left to ask again; nothing it calls will be started");
154	        endingInvalid = true;
155	      } else if (reask === "loop") {
156	        // The loop guard's verdict stays in the session, which is where
157	        // post_result_comment.ts reads it: a run that gets no second turn still
158	        // names the call that repeated in its comment.
159	        console.error("::warning::the loop guard stopped this run and there is no time left to ask again");

