1	/**
2	 * decide_reask.test.ts  Ethe one second turn a run is allowed, and the bounds
3	 * around it.
4	 *
5	 * The counting is `domain/work/ending-calls.test.ts`'s and the scripts it calls
6	 * have their own files; what this pins is the orchestration, which is the part
7	 * a refactor can break without anything failing: that a failed or stopped first
8	 * turn is never asked, that the second turn runs only when there is time for it,
9	 * that the session is restored when the second attempt dies, and that a person's
10	 * stop during the ask outranks everything the machinery was about to do.
11	 *
12	 * The second turn is `sudo ... atoma run`, and tests cannot run sudo  Eso a fake
13	 * `sudo` on PATH stands in for it, driven by `FAKE_SUDO_MODE`. What the fake
14	 * answers for is the exec and its exit code; the launch library's argv is held
15	 * by the contract tests on the generated workflow.
16	 */
17	import { describe, expect, test } from "bun:test";
18	import { spawnSync } from "node:child_process";
19	import { chmodSync, mkdirSync, mkdtempSync, readFileSync, writeFileSync } from "node:fs";
20	import { tmpdir } from "node:os";
21	import { join } from "node:path";
22	import { hermeticEnv, removeTemp, scriptPath } from "./testing/harness.ts";
23	
24	/** The breaking ending: two calls, the fixture `check_ending` refuses. */
25	const BREAKING = "Done.\n\n/engineer\n\n@alice, your call.";
26	const PEOPLE = JSON.stringify({ humans: ["alice", "bob"], notify: "alice" });
27	const SESSION = JSON.stringify({ messages: [{ role: "assistant", content: BREAKING }] });
28	
29	/**
30	 * A run the loop guard stopped, in the shape a real one arrives in (#610): atoma
31	 * records the verdict beside `ended_because: "failed"`, because its `soft_stop_ending`
32	 * maps only a different guard that watches the model's own output. So the run reaches
33	 * here as a failure with exit 1 and the verdict in the session, and neither the exit
34	 * code nor the ending word may be what the decision reads.
35	 */
36	const LOOP_ABORT = {
37	  rule: "identical_answers",
38	  tool: "read",
39	  arguments: '{"path":"src/domain/tool_loop.rs"}',
40	  count: 4,
41	  call: 5,
42	  capped: false,
43	  last_error: null,
44	};
45	const LOOP = JSON.stringify({
46	  messages: [{ role: "assistant", content: "", tool_calls: [{ function: { name: "read" } }] }],
47	  atoma_runs: [{ ended_because: "failed", loop_abort: LOOP_ABORT }],
48	});
49	
50	interface RunResult {
51	  status: number;
52	  stdout: string;
53	  /** The session's roles after the decision, in order. */
54	  messages: string[];
55	  /** What the machinery told the run, in order. */
56	  notes: string[];
57	  output: string;
58	}
