60	function makeSudo(dir: string): string {
61	  const bin = join(dir, "bin");
62	  mkdirSync(bin, { recursive: true });
63	  writeFileSync(
64	    join(bin, "sudo"),
65	    [
66	      "#!/usr/bin/env bash",
67	      '# Fakes `sudo -n -u USER env ... atoma run ...`  Ethe exec and its exit code.',
68	      'mode="${FAKE_SUDO_MODE:-ok}"',
69	      'if [ "$mode" = "stop" ]; then',
70	      '  prev=""',
71	      '  for a in "$@"; do',
72	      '    if [ "$prev" = "--stop-file" ]; then touch "$a"; fi',
73	      '    prev="$a"',
74	      "  done",
75	      '  echo "stopped mid-sentence"',
76	      "  # atoma saw the stop and answered with its own soft stop.",
77	      "  exit 2",
78	      "fi",
79	      'if [ "$mode" = "fail" ]; then',
80	      '  echo "the second attempt died" >&2',
81	      "  exit 3",
82	      "fi",
83	      'echo "Done; nothing left to run."',
84	      "exit 0",
85	      "",
86	    ].join("\n"),
87	  );
88	  // Windows resolves `sudo` through PATHEXT to sudo.cmd below, where execute
89	  // bits do not exist; a POSIX runner needs the bit, or the exec fails and the
90	  // second turn reads as failed.
91	  if (process.platform !== "win32") chmodSync(join(bin, "sudo"), 0o755);
92	  // The sh spelling is what a Linux runner executes; the .cmd spelling is what
93	  // Windows resolves through PATHEXT when these tests run on a checkout.
94	  writeFileSync(
95	    join(bin, "sudo.cmd"),
96	    [
97	      "@echo off",
98	      'if /i "%FAKE_SUDO_MODE%"=="stop" goto stop',
99	      'if /i "%FAKE_SUDO_MODE%"=="fail" goto fail',
100	      "echo Done; nothing left to run.",
101	      "exit /b 0",
102	      ":stop",
103	      'set "prev="',
104	      'set "stopfile="',
105	      ":nextarg",
106	      'if "%~1"=="" goto stopped',
107	      'if "%prev%"=="--stop-file" set "stopfile=%~1"',
108	      'set "prev=%~1"',
109	      "shift",
110	      "goto nextarg",
111	      ":stopped",
112	      'if not "%stopfile%"=="" type nul > "%stopfile%"',
113	      "echo stopped mid-sentence",
114	      "rem atoma saw the stop and answered with its own soft stop.",
115	      "exit /b 2",
116	      ":fail",
117	      "echo the second attempt died 1>&2",
118	      "exit /b 3",
119	      "",
120	    ].join("\r\n"),
121	  );
122	  return bin;
123	}
