125	function run(opts: {
126	  exitCode: string;
127	  mode?: "ok" | "fail" | "stop";
128	  deadlineOffsetSecs?: number;
129	  output?: string;
130	  /** The session atoma left; the breaking ending by default. */
131	  session?: string;
132	  withStopFile?: boolean;
133	}): RunResult & { dir: string } {
134	  const dir = mkdtempSync(join(tmpdir(), "atomaton-reask-"));
135	  const bin = makeSudo(dir);
136	  // The definitions live under the machinery root's `.github/atomaton/`, exactly
137	  // where a deployed tree carries them  Ethe decision resolves them itself.
138	  const defs = join(dir, ".github", "atomaton", "agent-definitions");
139	  mkdirSync(defs, { recursive: true });
140	  writeFileSync(join(defs, "engineer.md"), "---\nname: engineer\n---\n");
141	  const runDir = join(dir, "run");
142	  mkdirSync(runDir, { recursive: true });
143	  writeFileSync(join(runDir, "session.json"), opts.session ?? SESSION);
144	  writeFileSync(join(runDir, "atomaton_output.txt"), opts.output ?? BREAKING);
145	  writeFileSync(join(runDir, "callees.json"), PEOPLE);
146	  if (opts.withStopFile) writeFileSync(join(optsStopPath(dir)), "stop");
147	
148	  const deadline = Math.floor(Date.now() / 1000) + (opts.deadlineOffsetSecs ?? 3600);
149	  // Windows joins PATH with `;`; the fake sudo must be found before any real one.
150	  const pathSep = process.platform === "win32" ? ";" : ":";
151	  const run = spawnSync(
152	    "bun",
153	    [
154	      "run", scriptPath("decide_reask.ts"),
155	      "--run-dir", runDir,
156	      "--tool-cache", join(dir, "cache"),
157	      "--tools-file", join(dir, "tools.yaml"),
158	      "--credentials-file", join(dir, "credentials.json"),
159	      "--stop-file", optsStopPath(dir),
160	      "--deadline-at", String(deadline),
161	      "--min-budget-secs", "60",
162	      "--exit-code", opts.exitCode,
163	    ],
164	    {
165	      encoding: "utf8",
166	      env: {
167	        ...hermeticEnv(),
168	        AGENT: "engineer",
169	        ATOMATON_MACHINERY_ROOT: dir,
170	        FAKE_SUDO_MODE: opts.mode ?? "ok",
171	        PATH: `${bin}${pathSep}${process.env.PATH ?? ""}`,
172	      },
173	    },
